      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided text does not mention the existence of similar systematic reviews; therefore, this conditional requirement does not apply."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "We aimed to assess the perioperative characteristics, management approaches, and outcomes of this intervention, which is used to achieve portal decompression and enable the safe performance of elective and emergent surgery.",
      "reason": "The authors briefly describe the mechanism of action of the intervention (TIPS) as achieving portal decompression."
    },
