{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "In this systematic review and meta-analysis, we examined the evidence on transjugular intrahepatic portosystemic shunt (TIPS) as a bridge to elective and emergency surgery in cirrhotic patients. We aimed to assess the perioperative characteristics, management approaches, and outcomes of this intervention",
      "reason": "The authors explicitly state the objective of the review in the abstract, which serves as the introduction/background section."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "The outcomes of interest were: 1. Surgery after TIPS; 2. Mortality; 3. Perioperative transfusions; and 4. Postoperative liver-related events.",
      "reason": "The review defines the outcomes of interest (the 'O' in PICO) and the intervention (TIPS) and population (cirrhotic patients undergoing surgery) are clearly defined in the objective statement, constituting a PICO-like structure for the review's scope."
    }
  ],
  "confidence": 100
}

